 "content": "def transform(grid):
    # Extend each marker horizontally and vertically across the grid.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for r, c, color in marks:
        for rr in range(h):
            if grid[rr][c] == 0:
                out[rr][c] = color
        for cc in range(w):
            if grid[r][cc] == 0:
                out[r][cc] = color
    return out
